a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: run_dca.R <pred.csv> <out> <times>");if(!requireNamespace("dcurves",quietly=TRUE)||!requireNamespace("ggplot2",quietly=TRUE)||!requireNamespace("dplyr",quietly=TRUE))stop("Install dcurves, ggplot2, dplyr");d<-read.csv(a[1],check.names=FALSE);out<-a[2];tt<-as.numeric(strsplit(a[3],",",TRUE)[[1]]);dir.create(out,recursive=TRUE,showWarnings=FALSE);for(t in tt){cols<-grep(paste0("__risk__",t,"$"),names(d),value=TRUE);if(!length(cols))next;dd<-d[,c("Time","Event",cols),drop=FALSE];names(dd)[-(1:2)]<-sub(paste0("__risk__",t,"$"),"",cols);f<-as.formula(paste("survival::Surv(Time,Event)~",paste(names(dd)[-(1:2)],collapse="+")));o<-dcurves::dca(f,data=dd,time=t);z<-dplyr::filter(as.data.frame(o),!is.na(net_benefit));write.csv(z,file.path(out,paste0("dca_",t,".csv")),row.names=FALSE);p<-ggplot2::ggplot(z,ggplot2::aes(threshold,net_benefit,color=label))+ggplot2::geom_line(linewidth=.8)+ggplot2::theme_classic()+ggplot2::labs(x="Threshold probability",y="Net benefit",color=NULL);ggplot2::ggsave(file.path(out,paste0("dca_",t,".pdf")),p,width=6,height=5.5)}
